  "private.assert_team_member": {
    "file": "20261104000002_app_core.sql",
    "comment": "-- ---- helper: raise unless p_usn is a member of p_team_id ----\n-- Without care this is WRITE SKEW: one transaction checks \"X is a member\" and records X's\n-- work, while another checks \"X has no work\" and deletes X's membership; each check passes\n-- on its own snapshot. So the check WRITES the membership row it relies on (a no-op UPDATE,\n-- the same \"serialize by writing\" idea as capacity v2 below). A concurrent DELETE of that\n-- row then waits for us and, under READ COMMITTED, its history guard re-reads and sees our\n-- row; under REPEATABLE READ / SERIALIZABLE it fails with 40001. (A lock alone, e.g. FOR\n-- KEY SHARE, would not do: under RR the deleter's snapshot predates our commit, and a\n-- row that was only locked, not changed, raises no serialization error.)\n-- Cost: one student's concurrent writes in the same team queue on that one row.",
    "sql": "CREATE FUNCTION private.assert_team_member(p_team_id VARCHAR, p_usn VARCHAR, p_rule TEXT)\nRETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$\nBEGIN\n    UPDATE public.team_member SET role = role\n    WHERE team_id = p_team_id AND usn = p_usn;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Student % is not a member of team %', p_usn, p_team_id\n            USING ERRCODE = 'check_violation', CONSTRAINT = p_rule, DETAIL = p_rule;\n    END IF;\nEND $$;"
  },
  "private.assert_milestone_open": {
    "file": "20261104000002_app_core.sql",
    "comment": "-- ---- helper: raise unless the component is still open (not locked) ----\n-- FOR SHARE: a concurrent lock_milestone() UPDATE waits for this transaction, or we wait\n-- for it and then see locked_at, so nothing slips in at lock time.",
    "sql": "CREATE FUNCTION private.assert_milestone_open(p_project_id VARCHAR, p_milestone_no INT, p_what TEXT)\nRETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$\nDECLARE v_locked TIMESTAMPTZ;\nBEGIN\n    SELECT locked_at INTO v_locked FROM public.milestone\n    WHERE project_id = p_project_id AND milestone_no = p_milestone_no\n    FOR SHARE;\n    IF v_locked IS NOT NULL THEN\n        RAISE EXCEPTION 'Milestone %/% is locked (since %); % can no longer change',\n            p_project_id, p_milestone_no, v_locked, p_what\n            USING ERRCODE = 'object_not_in_prerequisite_state', CONSTRAINT = 'milestone_locked',\n                  DETAIL = 'milestone_locked';\n    END IF;\nEND $$;"
  },
  "private.enforce_team_capacity_v2": {
    "file": "20261104000002_app_core.sql",
    "comment": "-- ---- (a) Team capacity v2: \"serialize by writing the parent row\" ----\n-- Why v2: the fixture's check_team_capacity() (Q35) only SELECTs the team row FOR UPDATE.\n-- Under REPEATABLE READ the snapshot is fixed before the lock wait and a lock is not a\n-- write, so the second joiner counts a stale 3/4 and over-admits to 5/4\n-- (experiments/race/FINDINGS.md). Here the trigger *writes* the team row (no-op UPDATE):\n--   READ COMMITTED  -> the 2nd joiner waits, then the COUNT (new statement = new snapshot)\n--                      sees the 1st joiner and is refused;\n--   REPEATABLE READ / SERIALIZABLE -> the 2nd joiner's UPDATE hits a row changed after its\n--                      snapshot: SQLSTATE 40001, the client retries and is then refused.\n-- Fires on INSERT and on UPDATE OF team_id (moving teams must not bypass the rule).",
    "sql": "CREATE FUNCTION private.enforce_team_capacity_v2()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$\nDECLARE\n    cap          INT;\n    current_size INT;\nBEGIN\n    IF TG_OP = 'UPDATE' AND NEW.team_id = OLD.team_id THEN\n        RETURN NEW;                                  -- not changing team: size unchanged\n    END IF;\n\n    -- 1. write-lock the parent row (also creates a new row version => RR/SER conflict)\n    UPDATE public.team SET max_size = max_size\n    WHERE team_id = NEW.team_id\n    RETURNING max_size INTO cap;\n    IF NOT FOUND THEN\n        RETURN NEW;                                  -- unknown team: the FK reports it\n    END IF;\n\n    -- 2. count only after the lock is held (the moving row is still under OLD.team_id)\n    SELECT count(*) INTO current_size FROM public.team_member WHERE team_id = NEW.team_id;\n    IF current_size >= cap THEN\n        RAISE EXCEPTION 'Team % is full (% / %)', NEW.team_id, current_size, cap\n            USING ERRCODE = 'check_violation', CONSTRAINT = 'team_capacity', DETAIL = 'team_capacity';\n    END IF;\n    RETURN NEW;\nEND $$;"
  },
  "private.guard_team_shrink": {
    "file": "20261104000002_app_core.sql",
    "comment": "-- ---- (b) Capacity cannot be bypassed by shrinking max_size below the member count ----",
    "sql": "CREATE FUNCTION private.guard_team_shrink()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$\nDECLARE n INT;\nBEGIN\n    IF NEW.max_size < OLD.max_size THEN\n        SELECT count(*) INTO n FROM public.team_member WHERE team_id = NEW.team_id;\n        IF n > NEW.max_size THEN\n            RAISE EXCEPTION 'Team % already has % members; max_size % is too small', NEW.team_id, n, NEW.max_size\n                USING ERRCODE = 'check_violation', CONSTRAINT = 'team_capacity', DETAIL = 'team_capacity';\n        END IF;\n    END IF;\n    RETURN NEW;\nEND $$;"
  },
  "private.enforce_one_team_per_project": {
    "file": "20261104000002_app_core.sql",
    "comment": "-- ---- (c) One team per project per student ----\n-- A cross-table rule (team_member.usn + team.project_id). Same write-lock trick, on the\n-- student row, so two concurrent joins by one student into two teams serialize.",
    "sql": "CREATE FUNCTION private.enforce_one_team_per_project()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$\nDECLARE\n    v_project  VARCHAR(5);\n    v_offering INT;\n    v_other    VARCHAR(5);\nBEGIN\n    IF TG_OP = 'UPDATE' AND NEW.team_id = OLD.team_id AND NEW.usn = OLD.usn THEN\n        RETURN NEW;\n    END IF;\n\n    UPDATE public.student SET usn = usn WHERE usn = NEW.usn;  -- no-op write = row lock\n\n    SELECT t.project_id, p.offering_id INTO v_project, v_offering\n    FROM public.team t JOIN public.project p ON p.project_id = t.project_id\n    WHERE t.team_id = NEW.team_id;\n\n    -- TEAM_MEMBER must respect ENROLLMENT: only students enrolled in the project's course\n    -- offering may join its teams. (Fixture projects have no offering: no rule to apply.)\n    IF v_offering IS NOT NULL AND NOT EXISTS (\n        SELECT 1 FROM public.enrollment WHERE usn = NEW.usn AND offering_id = v_offering) THEN\n        RAISE EXCEPTION 'Student % is not enrolled in the course offering of project %', NEW.usn, v_project\n            USING ERRCODE = 'check_violation', CONSTRAINT = 'team_member_enrolled_required',\n                  DETAIL = 'team_member_enrolled_required';\n    END IF;\n\n    SELECT tm.team_id INTO v_other\n    FROM public.team_member tm\n    JOIN public.team t ON t.team_id = tm.team_id\n    WHERE tm.usn = NEW.usn\n      AND t.project_id = v_project\n      AND tm.team_id <> NEW.team_id\n      AND NOT (TG_OP = 'UPDATE' AND tm.team_id = OLD.team_id AND tm.usn = OLD.usn)\n    LIMIT 1;\n\n    IF v_other IS NOT NULL THEN\n        RAISE EXCEPTION 'Student % is already in team % for project %', NEW.usn, v_other, v_project\n            USING ERRCODE = 'unique_violation', CONSTRAINT = 'one_team_per_project',\n                  DETAIL = 'one_team_per_project';\n    END IF;\n    RETURN NEW;\nEND $$;"
  },
