  "private.guard_member_history": {
    "file": "20261104000002_app_core.sql",
    "comment": "-- ---- (c2) History pins membership ----\n-- A student who has recorded anything in a team (claims, countersigns, contributions,\n-- versions, chunks, owned artifacts, submissions, or marks in the project) cannot leave\n-- it, by ANY path: the leave_team RPC, a direct DELETE through the API, or an UPDATE that\n-- moves the row. Otherwise \"the claimant / endorser / assessed student is a member\" would\n-- silently stop holding (and a leaver's countersign would still count).\n-- The DELETE takes the row lock before this trigger runs, so it waits for any transaction\n-- that wrote the row in assert_team_member, then (RC) sees that one's work or (RR) gets 40001.\n-- A cascade from deleting the STUDENT is let through: every history table references\n-- student ON DELETE RESTRICT, so that delete fails anyway with the proper FK error.",
    "sql": "CREATE FUNCTION private.guard_member_history()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$\nDECLARE v_project VARCHAR(5);\nBEGIN\n    IF TG_OP = 'UPDATE' AND NEW.team_id = OLD.team_id AND NEW.usn = OLD.usn THEN\n        RETURN NEW;\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM public.student WHERE usn = OLD.usn) THEN\n        RETURN OLD;                                  -- cascade from deleting the student\n    END IF;\n    SELECT project_id INTO v_project FROM public.team WHERE team_id = OLD.team_id;\n\n    IF EXISTS (SELECT 1 FROM public.claim WHERE team_id = OLD.team_id AND usn = OLD.usn)\n       OR EXISTS (SELECT 1 FROM public.countersign cs JOIN public.claim c ON c.claim_id = cs.claim_id\n                  WHERE c.team_id = OLD.team_id AND cs.endorser_usn = OLD.usn)\n       OR EXISTS (SELECT 1 FROM public.artifact a\n                  WHERE a.team_id = OLD.team_id\n                    AND (a.owner_usn = OLD.usn\n                         OR EXISTS (SELECT 1 FROM public.contribution k\n                                    WHERE k.artifact_id = a.artifact_id AND k.usn = OLD.usn)\n                         OR EXISTS (SELECT 1 FROM public.artifact_version v\n                                    WHERE v.artifact_id = a.artifact_id AND v.created_by = OLD.usn)\n                         OR EXISTS (SELECT 1 FROM public.artifact_chunk ch\n                                    WHERE ch.artifact_id = a.artifact_id AND ch.author_usn = OLD.usn)))\n       OR EXISTS (SELECT 1 FROM public.submission WHERE team_id = OLD.team_id AND submitted_by = OLD.usn)\n       OR EXISTS (SELECT 1 FROM public.assessment WHERE project_id = v_project AND usn = OLD.usn) THEN\n        RAISE EXCEPTION 'Student % has recorded work in team %, so the membership cannot be removed',\n            OLD.usn, OLD.team_id\n            USING ERRCODE = 'object_not_in_prerequisite_state', CONSTRAINT = 'leave_team_has_history',\n                  DETAIL = 'leave_team_has_history',\n                  HINT = 'Claims, countersigns, contributions and marks stay with the team they were made in.';\n    END IF;\n    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;\nEND $$;"
  },
